// src/view/region-delete-dialog.js
function openRegionDeleteDialog(doc, { message = "", onDelete, onOpen, onCancel } = {}) {
  const root = doc.createElement("div");
  root.className = "pxd-view-dialog";
  root.setAttribute("role", "dialog");
  root.setAttribute("aria-label", "Delete region");
  const stop2 = (event) => event.stopPropagation();
  root.addEventListener("pointerdown", stop2);
  root.addEventListener("mousedown", stop2);
  root.addEventListener("click", stop2);
  const card2 = doc.createElement("form");
  card2.className = "pxd-view-dialog__card";
  card2.addEventListener("submit", (event) => event.preventDefault());
  root.append(card2);
  const text3 = doc.createElement("p");
  text3.className = "pxd-region-delete__message";
  text3.textContent = message;
  card2.append(text3);
  const actions = doc.createElement("div");
  actions.className = "pxd-view-dialog__actions";
  const button = (cls, label, run) => {
    const node2 = doc.createElement("button");
    node2.type = "button";
    node2.className = `pxd-btn ${cls}`;
    node2.textContent = label;
    node2.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      run?.();
    });
    return node2;
  };
  const cancel = button("pxd-region-delete-cancel", "Cancel", onCancel);
  actions.append(
    button("pxd-region-delete", "Delete", onDelete),
    button("pxd-region-open-refs", "Open references", onOpen),
    cancel
  );
  card2.append(actions);
  let closed = false;
  const close = () => {
    if (closed) return;
    closed = true;
    root.remove();
  };
  root.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    event.stopPropagation();
    onCancel?.();
  });
  return {
    el: root,
    close,
    // The safe choice takes focus once the dialog is in the tree, so Escape and Enter reach it.
    focus() {
      try {
        cancel.focus();
      } catch {
      }
    }
  };
}

